 <div class="admin-table-wrap"><table><thead><tr><th>Date UTC</th><th>Sens</th><th>Montant</th><th>Motif</th><th>Pièce</th><th>Note</th><th>Saisi par</th></tr></thead><tbody><?php foreach($report['cash'] as $row): ?><tr><td><?= $escape($row['occurred_at']) ?></td><td><?= $row['direction']==='in'?'Entrée':'Sortie' ?></td><td><?= $money((int)$row['amount']) ?></td><td><?= $escape($row['category']) ?></td><td><?= $escape($row['reference']) ?></td><td><?= $escape($row['note']) ?></td><td><?= $escape($row['actor']??'Compte supprimé') ?></td></tr><?php endforeach; ?><?php if(!$report['cash']): ?><tr><td colspan="7">Aucune écriture de caisse sur cette période.</td></tr><?php endif; ?></tbody></table></div></section>
